def main():
 for f,s in stubs.items():p=B/'tests/api'/f;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,'utf8')
 # Unused previous icon stubs need richer Context than this fixture; compile
 # only types reachable from the updater, never those historical extras.
 sources=[B/'tests/api'/f for f in stubs if f not in ['android/widget/ImageView.java','android/widget/FrameLayout.java']]
 classes=B/'test-classes';classes.mkdir(exist_ok=True)
 args=[JAVA,'-jar',T/'ecj.jar','-proc:none','-source','8','-target','8','-warn:none','-encoding','UTF-8','-cp',ANDROID,'-d',classes,*sources,*list((B/'src').rglob('*.java')),B/'tests/UpdatesTest.java']
 p=subprocess.run(list(map(str,args)),capture_output=True,text=True,encoding='utf8',errors='replace');print(p.stdout,p.stderr);p.check_returncode()
 p=subprocess.run([str(JAVA),'-cp',str(classes),'com.hljzjx.md3.updates.UpdatesTest'],capture_output=True,text=True,encoding='utf8',errors='replace');print(p.stdout,p.stderr);p.check_returncode()
 report={'result':p.stdout.strip(),'source_sha256':hashlib.sha256((B/'src/com/hljzjx/md3/updates/ManualUpdates.java').read_bytes()).hexdigest(),'scope':'actual own Java with observable Android lifecycle, dialogs, downloads and browser fixtures; no HTTP or Android rendering'}
 (B/'update-tests.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),'utf8')
if __name__=='__main__':main()
